import{_ as a,o as t,c as n,a5 as i}from"./chunks/framework.bIR-4glx.js";const m=JSON.parse('{"title":"Reader Field Note: What Remains Seven Days Later","description":"Use a private-first two-pass record to connect reading entry, real action, immediate result, delayed retention, failed transfer, and editorial feedback before deciding whether to share publicly.","frontmatter":{"title":"Reader Field Note: What Remains Seven Days Later","description":"Use a private-first two-pass record to connect reading entry, real action, immediate result, delayed retention, failed transfer, and editorial feedback before deciding whether to share publicly.","updated":"2026-09-02T00:00:00.000Z","worksheetDownload":{"url":"/downloads/worksheets/reader-field-note.en.md","name":"reader-field-note.en.md"}},"headers":[],"relativePath":"en/templates/reader-field-note.md","filePath":"en/templates/reader-field-note.md","lastUpdated":1788307200000}'),s={name:"en/templates/reader-field-note.md"};function r(o,e,l,d,h,p){return t(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="reader-field-note-what-remains-seven-days-later" tabindex="-1">Reader Field Note: What Remains Seven Days Later <a class="header-anchor" href="#reader-field-note-what-remains-seven-days-later" aria-label="Permalink to &quot;Reader Field Note: What Remains Seven Days Later&quot;">​</a></h1><p>This field note is not a book review and does not ask you to prove that a book works. It follows a plainer path: <strong>what brought you in, what you did after reading, and what remained several days later.</strong></p><p>Copy it into a private note first. Complete the first pass within ten minutes of reading and the second pass three to seven days later. Do not repeatedly reread the chapter just to complete the form. The second record matters because fewer prompts remain.</p><p>Public sharing is always optional. Names, employers, customers, relationships, health, finances, and conversation content that lack permission should not enter a public note merely to make it look “real”.</p><h2 id="complete-it-privately-first" tabindex="-1">Complete It Privately First <a class="header-anchor" href="#complete-it-privately-first" aria-label="Permalink to &quot;Complete It Privately First&quot;">​</a></h2><p>A useful field note answers only four things:</p><ol><li>What real problem did I bring to the page?</li><li>What did I actually make or do rather than merely agree with?</li><li>Three to seven days later, could I act again with fewer prompts or under a changed condition?</li><li>Which passage supported action, and which remained abstract, unsafe, or unusable?</li></ol><p>It is valid to record no action or no retest. “This produced agreement but no action yet” is evidence. You do not need to invent a success story to complete the sheet.</p><h2 id="first-pass-ten-minutes-after-reading" tabindex="-1">First Pass: Ten Minutes after Reading <a class="header-anchor" href="#first-pass-ten-minutes-after-reading" aria-label="Permalink to &quot;First Pass: Ten Minutes after Reading&quot;">​</a></h2><h3 id="_1-entry-problem" tabindex="-1">1. Entry Problem <a class="header-anchor" href="#_1-entry-problem" aria-label="Permalink to &quot;1. Entry Problem&quot;">​</a></h3><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Date:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Chapter or page:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Why I opened it:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Real situation at the time:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">What I could already do before reading:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Where I was stuck before reading:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Time and capacity available today:</span></span></code></pre></div><p>Do not write “I want to improve myself”. Name a situation that can occur, such as: “I need to hand project risks to a colleague, but the current record contains only chat messages and scattered screenshots.”</p><h3 id="_2-retell-it-in-your-own-words" tabindex="-1">2. Retell It in Your Own Words <a class="header-anchor" href="#_2-retell-it-in-your-own-words" aria-label="Permalink to &quot;2. Retell It in Your Own Words&quot;">​</a></h3><p>Close the page and use no more than three sentences:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Core judgment as I understand it:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Fact, example, or source supporting it:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">What it still cannot prove for me:</span></span></code></pre></div><p>If you can only copy the original wording, do not rush to rate the chapter. Write “I cannot explain this in my own words yet”. That is more accurate than a polished quotation.</p><h3 id="_3-take-one-minimum-action" tabindex="-1">3. Take One Minimum Action <a class="header-anchor" href="#_3-take-one-minimum-action" aria-label="Permalink to &quot;3. Take One Minimum Action&quot;">​</a></h3><p>Choose an action that can end within 10–45 minutes and leaves something visible.</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Minimum action I will complete:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Acceptance standard:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">AI or human assistance used:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">What I must decide myself:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Location of the artifact, recording, code, or note:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Stop condition:</span></span></code></pre></div><p>Possible actions include rewriting an email, recording an explanation, repairing one test, creating a learning-state page, removing an invalid requirement, or confirming a boundary with someone affected. Saving more material is not an action.</p><h3 id="_4-preserve-the-immediate-result" tabindex="-1">4. Preserve the Immediate Result <a class="header-anchor" href="#_4-preserve-the-immediate-result" aria-label="Permalink to &quot;4. Preserve the Immediate Result&quot;">​</a></h3><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">What I actually completed:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">What remained incomplete:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Direct feedback or outcome:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Largest error or resistance:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">The conclusion I am most tempted to exaggerate:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Next retest date:</span></span></code></pre></div><p>An immediate success shows only what happened under the present conditions. If AI was used, keep the assisted version separate from the independent version completed after closing it.</p><h2 id="second-pass-three-to-seven-days-later" tabindex="-1">Second Pass: Three to Seven Days Later <a class="header-anchor" href="#second-pass-three-to-seven-days-later" aria-label="Permalink to &quot;Second Pass: Three to Seven Days Later&quot;">​</a></h2><h3 id="_5-retest-before-rereading" tabindex="-1">5. Retest before Rereading <a class="header-anchor" href="#_5-retest-before-rereading" aria-label="Permalink to &quot;5. Retest before Rereading&quot;">​</a></h3><p>Do not open the original chapter, chat, or answer first. Complete a related task and then record:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Retest date and interval:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Prompts removed:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Related task:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">What I completed independently:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Prompts still needed:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">What genuinely remained from the first attempt:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Evidence location:</span></span></code></pre></div><p>If nothing returns, do not convert the result into “I was busy”. Record the fact first. Then decide whether the task was too large, the entry unclear, or the chapter produced only short-term agreement.</p><h3 id="_6-change-one-condition" tabindex="-1">6. Change One Condition <a class="header-anchor" href="#_6-change-one-condition" aria-label="Permalink to &quot;6. Change One Condition&quot;">​</a></h3><p>For transfer, change only one condition: topic, audience, time limit, material, tool permission, or purpose.</p><table tabindex="0"><thead><tr><th>Changed condition</th><th>New task</th><th>Independent result</th><th>Where it failed</th><th>Next step</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p>A failed transfer is not a bad review. It exposes the boundary of a method and helps an author distinguish a sentence that sounds right from something a reader can actually use.</p><h3 id="_7-give-editorial-feedback" tabindex="-1">7. Give Editorial Feedback <a class="header-anchor" href="#_7-give-editorial-feedback" aria-label="Permalink to &quot;7. Give Editorial Feedback&quot;">​</a></h3><p>Point to a specific paragraph, heading, example, or tool whenever possible:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Passage that most supported action:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Passage that remained abstract or unusable:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Missing boundary, example, or prerequisite:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Passage that could be removed or shortened:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Part that did not work when I tried it:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Question I hope the next edition answers:</span></span></code></pre></div><p>“This is excellent” may encourage the author but rarely changes the next edition. “I followed step three but could not define the acceptance standard” carries more editorial value.</p><h2 id="separate-fact-interpretation-and-wish" tabindex="-1">Separate Fact, Interpretation, and Wish <a class="header-anchor" href="#separate-fact-interpretation-and-wish" aria-label="Permalink to &quot;Separate Fact, Interpretation, and Wish&quot;">​</a></h2><p>Before sharing, check whether three layers have been mixed:</p><table tabindex="0"><thead><tr><th>Layer</th><th>Example</th></tr></thead><tbody><tr><td>Fact</td><td>Seven days later, without the page, I completed two requirements and needed a prompt for the third</td></tr><tr><td>Interpretation</td><td>The example may have helped me retain the structure, while the boundary remained abstract</td></tr><tr><td>Wish</td><td>I hope the next edition includes one fully completed example</td></tr></tbody></table><p>Do not turn one personal result into “this works for everyone”, or one failure into “the method is useless”. Keep the task, conditions, and sample so the conclusion retains boundaries.</p><h2 id="privacy-gate-before-sharing" tabindex="-1">Privacy Gate before Sharing <a class="header-anchor" href="#privacy-gate-before-sharing" aria-label="Permalink to &quot;Privacy Gate before Sharing&quot;">​</a></h2><p>Consider public sharing only when every item passes:</p><ul><li>[ ] Passwords, keys, identity documents, exact addresses, and private contact details are removed;</li><li>[ ] Customer data, company secrets, medical records, and non-public financial information are removed;</li><li>[ ] Unnecessary third-party names, photos, relationships, and identifying details are removed;</li><li>[ ] Material involving others is authorised or reduced to non-identifying minimum facts;</li><li>[ ] Direct observation, personal interpretation, and next hypothesis are separated;</li><li>[ ] I accept that this record may remain public and searchable for a long time.</li></ul><p>If any item is uncertain, keep the note private. An author does not need your privacy in order to improve a book.</p><h2 id="when-to-move-into-an-evidence-chain" tabindex="-1">When to Move into an Evidence Chain <a class="header-anchor" href="#when-to-move-into-an-evidence-chain" aria-label="Permalink to &quot;When to Move into an Evidence Chain&quot;">​</a></h2><p>A Reader Field Note answers whether one reading entered action. When one ability needs several comparable samples, scoring conditions, delayed retention, and transfer across contexts, move the record into the <a href="./evidence-chain">Evidence Chain Template</a>.</p><p>For a completed walkthrough, read <a href="./toolkit-walkthrough">Toolkit Walkthrough: Let AI Continue a 90-Day Learning Project across Sessions</a>. It uses synthetic data to show how Learning State, an AI task, an artifact, a retest, and this field note connect.</p><p>After the privacy gate, you may optionally submit a <a href="https://github.com/byoungd/up/issues/new?template=reader-field-note.yml" target="_blank" rel="noreferrer">public Reader Field Note</a>. Public sharing does not determine the value of the practice.</p><p>Related entry points: <a href="./../threads/part-5/book-as-proof">Case Study: Let the Book Prove Its Method</a> | <a href="./toolkit">Toolkit Overview</a> | <a href="./weekly-review">Weekly Review</a></p>`,49)])])}const u=a(s,[["render",r]]);export{m as __pageData,u as default};
